namespace NieFarm.Domain.Enums;

/// <summary>
/// The three fixed regions of the home page's "Vietnam Coffee Stories" map. Exactly one
/// <see cref="Entities.CoffeeRegion"/> row exists per value.
///
/// The values are persisted as an int and must never be renumbered: the database guards them
/// with a unique index and the check constraint <c>CK_CoffeeRegions_Key</c> (<c>[Key] IN (1, 2, 3)</c>),
/// and the Web layer maps each value to fixed SVG geometry generated by <c>tools/map</c>
/// (<c>Content/VietnamMapGeometry.g.cs</c>). Adding a region therefore needs a migration and new
/// geometry, which is intended.
/// </summary>
public enum CoffeeRegionKey
{
    North = 1,
    Central = 2,
    South = 3
}
